import{_ as o,r as n,o as p,c as l,e as t,a as i,s as c}from"./chunks/framework.CXcwiNg-.js";const y=JSON.parse('{"title":"Including Partials - October CMS User Guide","titleTemplate":false,"description":"Extract reusable template fragments into partials","frontmatter":{"subtitle":"Extract reusable template fragments into partials"},"headers":[{"level":2,"title":"Create a Partial","slug":"create-a-partial","link":"#create-a-partial","children":[]},{"level":2,"title":"Include It in the Layout","slug":"include-it-in-the-layout","link":"#include-it-in-the-layout","children":[]},{"level":2,"title":"Passing Variables to Partials","slug":"passing-variables-to-partials","link":"#passing-variables-to-partials","children":[]},{"level":2,"title":"Partials as UI Components","slug":"partials-as-ui-components","link":"#partials-as-ui-components","children":[{"level":3,"title":"Create the Button Partial","slug":"create-the-button-partial","link":"#create-the-button-partial","children":[]},{"level":3,"title":"Use the Button on a Page","slug":"use-the-button-on-a-page","link":"#use-the-button-on-a-page","children":[]},{"level":3,"title":"Why This Matters","slug":"why-this-matters","link":"#why-this-matters","children":[]}]},{"level":2,"title":"Next Steps","slug":"next-steps","link":"#next-steps","children":[]}],"relativePath":"user-guide/quickstart/editor/including-partials.md","filePath":"user-guide/quickstart/editor/including-partials.md"}'),r={name:"user-guide/quickstart/editor/including-partials.md"};function u(g,a,d,k,h,m){const s=n("pre-heading"),e=n("post-heading");return p(),l("div",null,[t(s),a[0]||(a[0]=i("h1",null,"Including Partials",-1)),t(e),a[1]||(a[1]=c(`<p>A <strong>partial</strong> is a reusable template fragment, a piece of HTML and Twig that you write once and include wherever you need it. Partials are ideal for things that appear in multiple places: navigation menus, footers, card layouts, sidebars, call-to-action banners.</p><p>The difference from content files: content files hold <strong>editable text</strong> (Markdown or plain HTML), while partials hold <strong>template markup</strong> with full Twig support.</p><h2 id="create-a-partial"><a href="#create-a-partial" class="header-anchor">#</a> Create a Partial</h2><p>Let&#39;s extract the footer from our layout into a partial so it can be reused.</p><ol><li>Navigate to <strong>Editor</strong> in the top menu, then click <strong>Partials</strong> in the side panel.</li><li>Click the <strong>+ Add</strong> button.</li><li>In the <strong>File Name</strong> field, enter <code>site-footer</code>.</li><li>In the markup editor, enter:</li></ol><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>footer</span> <span class="token attr-name">class</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>bg-white border-t mt-16<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>div</span> <span class="token attr-name">class</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>max-w-4xl mx-auto px-6 py-6 text-center text-sm text-gray-400<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
        <span class="token entity named-entity" title="©">&amp;copy;</span> <span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> <span class="token string"><span class="token punctuation">&#39;</span>now<span class="token punctuation">&#39;</span></span><span class="token operator">|</span>date<span class="token punctuation">(</span><span class="token string"><span class="token punctuation">&#39;</span>Y<span class="token punctuation">&#39;</span></span><span class="token punctuation">)</span> <span class="token delimiter punctuation">}}</span></span> My Website
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>div</span><span class="token punctuation">&gt;</span></span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>footer</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><ol start="5"><li>Click <strong>Save</strong>.</li></ol><h2 id="include-it-in-the-layout"><a href="#include-it-in-the-layout" class="header-anchor">#</a> Include It in the Layout</h2><ol><li>Open <strong>Editor → Layouts → default</strong>.</li><li>Find the <code>&lt;footer&gt;</code> block and replace it with:</li></ol><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">partial</span> <span class="token string"><span class="token punctuation">&#39;</span>site-footer<span class="token punctuation">&#39;</span></span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><ol start="3"><li>Click <strong>Save</strong> and preview the site.</li></ol><p>The page looks exactly the same, but now the footer markup lives in its own file. If you ever need to change the footer, you update it in one place and every layout that includes it gets the change.</p><h2 id="passing-variables-to-partials"><a href="#passing-variables-to-partials" class="header-anchor">#</a> Passing Variables to Partials</h2><p>Partials can accept variables, making them flexible. For example, you could make the site name configurable:</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">partial</span> <span class="token string"><span class="token punctuation">&#39;</span>site-footer<span class="token punctuation">&#39;</span></span> siteName<span class="token operator">=</span><span class="token string"><span class="token punctuation">&quot;</span>My Website<span class="token punctuation">&quot;</span></span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><p>Inside the partial, use the variable:</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>div</span> <span class="token attr-name">class</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>max-w-4xl mx-auto px-6 py-6 text-center text-sm text-gray-400<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
    <span class="token entity named-entity" title="©">&amp;copy;</span> <span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> <span class="token string"><span class="token punctuation">&#39;</span>now<span class="token punctuation">&#39;</span></span><span class="token operator">|</span>date<span class="token punctuation">(</span><span class="token string"><span class="token punctuation">&#39;</span>Y<span class="token punctuation">&#39;</span></span><span class="token punctuation">)</span> <span class="token delimiter punctuation">}}</span></span> <span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> siteName <span class="token delimiter punctuation">}}</span></span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>div</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><p>This is especially useful for partials like cards, hero sections, or any component where the structure stays the same but the content changes.</p><h2 id="partials-as-ui-components"><a href="#partials-as-ui-components" class="header-anchor">#</a> Partials as UI Components</h2><p>Partials can do more than just include a chunk of HTML. They can act as full UI components that accept content inside them. Let&#39;s build a reusable styled button.</p><h3 id="create-the-button-partial"><a href="#create-the-button-partial" class="header-anchor">#</a> Create the Button Partial</h3><ol><li>Go to <strong>Editor → Partials</strong> and click <strong>+ Add</strong>.</li><li>Name it <code>btn</code>.</li><li>Enter the following markup:</li></ol><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">props</span> <span class="token punctuation">{</span>href<span class="token punctuation">:</span> <span class="token string"><span class="token punctuation">&#39;</span>#<span class="token punctuation">&#39;</span></span><span class="token punctuation">,</span> style<span class="token punctuation">:</span> <span class="token string"><span class="token punctuation">&#39;</span>primary<span class="token punctuation">&#39;</span></span><span class="token punctuation">}</span> <span class="token delimiter punctuation">%}</span></span>

<span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">set</span> colors <span class="token operator">=</span> style <span class="token operator">==</span> <span class="token string"><span class="token punctuation">&#39;</span>primary<span class="token punctuation">&#39;</span></span>
    <span class="token operator">?</span> <span class="token string"><span class="token punctuation">&#39;</span>bg-blue-600 text-white hover:bg-blue-700<span class="token punctuation">&#39;</span></span>
    <span class="token punctuation">:</span> <span class="token string"><span class="token punctuation">&#39;</span>bg-gray-200 text-gray-800 hover:bg-gray-300<span class="token punctuation">&#39;</span></span> <span class="token delimiter punctuation">%}</span></span>

<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>a</span> <span class="token attr-name">href</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span><span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> href <span class="token delimiter punctuation">}}</span></span><span class="token punctuation">&quot;</span></span> <span class="token attr-name"><span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> attributes<span class="token punctuation">.</span>merge<span class="token punctuation">(</span><span class="token punctuation">{</span>class<span class="token punctuation">:</span> <span class="token string"><span class="token punctuation">&#39;</span>inline-block px-5 py-2.5 rounded-lg font-medium transition <span class="token punctuation">&#39;</span></span> <span class="token operator">~</span> colors<span class="token punctuation">}</span><span class="token punctuation">)</span> <span class="token delimiter punctuation">}}</span></span></span><span class="token punctuation">&gt;</span></span>
    <span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> body<span class="token operator">|</span>raw <span class="token delimiter punctuation">}}</span></span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>a</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><ol start="4"><li>Click <strong>Save</strong>.</li></ol><p>This partial uses <code>{% props %}</code> to declare two parameters: <code>href</code> and <code>style</code>. Any other attributes you pass (like <code>class</code> or <code>id</code>) flow into the <code>attributes</code> bag and get merged onto the element automatically.</p><h3 id="use-the-button-on-a-page"><a href="#use-the-button-on-a-page" class="header-anchor">#</a> Use the Button on a Page</h3><ol><li>Open <strong>Editor → Pages → Home</strong>.</li><li>Add a couple of buttons to the markup:</li></ol><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">partial</span> <span class="token string"><span class="token punctuation">&#39;</span>btn<span class="token punctuation">&#39;</span></span> href<span class="token operator">=</span><span class="token string"><span class="token punctuation">&quot;</span>/<span class="token punctuation">&quot;</span></span> style<span class="token operator">=</span><span class="token string"><span class="token punctuation">&quot;</span>primary<span class="token punctuation">&quot;</span></span> body <span class="token delimiter punctuation">%}</span></span>
    Get Started
<span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">endpartial</span> <span class="token delimiter punctuation">%}</span></span>

<span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">partial</span> <span class="token string"><span class="token punctuation">&#39;</span>btn<span class="token punctuation">&#39;</span></span> href<span class="token operator">=</span><span class="token string"><span class="token punctuation">&quot;</span>/about<span class="token punctuation">&quot;</span></span> style<span class="token operator">=</span><span class="token string"><span class="token punctuation">&quot;</span>secondary<span class="token punctuation">&quot;</span></span> body <span class="token delimiter punctuation">%}</span></span>
    Learn More
<span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">endpartial</span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><ol start="3"><li>Click <strong>Save</strong> and preview the page.</li></ol><p>You should see two styled buttons, a blue primary button and a grey secondary button. The <code>body</code> keyword lets you pass the button label as content inside the partial tag, rather than as a variable.</p><h3 id="why-this-matters"><a href="#why-this-matters" class="header-anchor">#</a> Why This Matters</h3><p>You now have a reusable button component. Need a button anywhere on your site? Use <code>{% partial &#39;btn&#39; %}</code> with the right props. Change the styling in one place and every button updates. This pattern works for any UI element: cards, alerts, badges, modals.</p><div class="custom-block aside"><p>For the full reference on partials, including the <code>{% props %}</code> tag and <code>attributes</code> API, see <a href="./../../../4.x/cms/themes/partials.html">Partials</a> in the developer documentation.</p></div><h2 id="next-steps"><a href="#next-steps" class="header-anchor">#</a> Next Steps</h2><p>Continue to <a href="./media-manager.html">Media Manager</a> to upload an image and display it on your page.</p>`,35))])}const b=o(r,[["render",u]]);export{y as __pageData,b as default};
